import in.aicon.pocket.Ledger;
public class LedgerTest { static int tests=0; static void eq(long a,long b){tests++;if(a!=b)throw new AssertionError(a+" != "+b);} public static void main(String[] x){eq(Ledger.amount("0.01"),1);eq(Ledger.amount("150.25"),15025);eq(Ledger.amount("9999999999.99"),999999999999L);for(String s:new String[]{"0","0.001","-1","1e2","abc","NaN","1,00","99999999999.99","",".5"}){tests++;try{Ledger.amount(s);throw new AssertionError(s);}catch(IllegalArgumentException e){}}for(int n=2;n<=100;n++)for(long t=1;t<350;t++){long sum=0,min=Long.MAX_VALUE,max=0;for(long a:Ledger.split(t,n)){sum+=a;min=Math.min(a,min);max=Math.max(a,max);}eq(sum,t);if(max-min>1)throw new AssertionError();}eq(Ledger.effect("income",100,"Cash","","Cash"),100);eq(Ledger.effect("expense",20,"Cash","","Cash"),-20);eq(Ledger.effect("transfer",30,"Cash","Bank","Cash"),-30);eq(Ledger.effect("transfer",30,"Cash","Bank","Bank"),30);eq(Ledger.effect("transfer",30,"Cash","Bank","Wallet"),0);eq(Ledger.effect("transfer",30,"Cash","Bank","Cash")+Ledger.effect("transfer",30,"Cash","Bank","Bank"),0);System.out.println("PASS "+tests+" assertions, exact money parsing, transfer invariants and equal splits.");}}
